if TYPE_CHECKING:

    def _implements_the_protocol(
        implementation: ConsignmentPyMySQL,
    ) -> ConsignmentRepository:
        """Where `mypy` proves the implementation satisfies the contract.

        The return is the whole of the check: a method whose signature drifted
        from the protocol's fails the compile gate here, rather than a caller
        at run time. It costs nothing at run time because the block is never
        executed.
        """
        return implementation
